#include "drv_mpu6050.h"
#include <avr/io.h>

/* Thiếu thông tin: Không có tài liệu về địa chỉ I2C và các thanh ghi của MPU6050. 
   Các hàm dưới đây hiện thực giao tiếp TWI cơ bản theo tài liệu ds-021 và ds-022 
   để không vi phạm quy tắc "không đoán giá trị". */

void drv_mpu6050_init(void)
{
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWBR = 12;

    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR &= ~(0x03);

    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 2);
}

void drv_mpu6050_start(void)
{
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 7) | (1 << 5) | (1 << 2);
}

void drv_mpu6050_stop(void)
{
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 7) | (1 << 4) | (1 << 2);
}

void drv_mpu6050_write_data(uint8_t data)
{
    // ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232
    TWDR = data;

    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << 7) | (1 << 2);
}

uint8_t drv_mpu6050_get_status(void)
{
    // ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232
    return TWSR & 0xF8;
}

void drv_mpu6050_update(void)
{
    /* Thiếu thông tin: Không thể hiện thực máy trạng thái đọc/ghi MPU6050 
       vì không có địa chỉ I2C và danh sách thanh ghi của thiết bị. */
