#include "drv_mpu6050.h"
#include <avr/io.h>

#define I2C_STATE_IDLE       0
#define I2C_STATE_START      1
#define I2C_STATE_SLA_W      2
#define I2C_STATE_REG_ADDR   3
#define I2C_STATE_DATA_W     4
#define I2C_STATE_REP_START  5
#define I2C_STATE_SLA_R      6
#define I2C_STATE_DATA_R     7

typedef struct {
    uint8_t reg_addr;
    uint8_t data;
    uint8_t is_read;
    uint8_t state;
    uint8_t error;
    uint8_t busy;
} i2c_trans_t;

static i2c_trans_t current_trans;

#define MPU_ST_INIT_WHOAMI 0
#define MPU_ST_WAIT_WHOAMI 1
#define MPU_ST_INIT_RESET  2
#define MPU_ST_WAIT_RESET  3
#define MPU_ST_DELAY_RESET 4
#define MPU_ST_INIT_WAKE   5
#define MPU_ST_WAIT_WAKE   6
#define MPU_ST_INIT_SMPLRT 7
#define MPU_ST_WAIT_SMPLRT 8
#define MPU_ST_INIT_CONFIG 9
#define MPU_ST_WAIT_CONFIG 10
#define MPU_ST_IDLE        11
#define MPU_ST_START_READ  12
#define MPU_ST_READING     13
#define MPU_ST_ERROR       14

static uint8_t mpu_state = MPU_ST_INIT_WHOAMI;
static uint16_t delay_counter = 0;
static uint8_t mpu_read_idx = 0;
static uint8_t mpu_raw_data[14];
static mpu6050_data_t mpu_latest_data;
static uint8_t mpu_data_valid = 0;

static const uint8_t mpu_regs[14] = {
    0x3B, 0x3C, 0x3D, 0x3E, 0x3F, 0x40,
    0x41, 0x42,
    0x43, 0x44, 0x45, 0x46, 0x47, 0x48
};

static void i2c_start_trans(uint8_t reg, uint8_t data, uint8_t is_read) {
    current_trans.reg_addr = reg;
    current_trans.data = data;
    current_trans.is_read = is_read;
    current_trans.state = I2C_STATE_START;
    current_trans.error = 0;
    current_trans.busy = 1;

    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN);
}

static void i2c_process(void) {
    if (!current_trans.busy) return;
    if (!(TWCR & (1 << TWINT))) return;

    // ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232
    uint8_t status = TWSR & 0xF8;

    switch (current_trans.state) {
        case I2C_STATE_START:
            if (status == 0x08 || status == 0x10) {
                TWDR = 0xD0;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWEN);
                current_trans.state = I2C_STATE_SLA_W;
            } else {
                current_trans.error = 1;
            }
            break;
        case I2C_STATE_SLA_W:
            if (status == 0x18) {
                TWDR = current_trans.reg_addr;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWEN);
                current_trans.state = I2C_STATE_REG_ADDR;
            } else {
                current_trans.error = 1;
            }
            break;
        case I2C_STATE_REG_ADDR:
            if (status == 0x28) {
                if (current_trans.is_read) {
                    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN);
                    current_trans.state = I2C_STATE_REP_START;
                } else {
                    TWDR = current_trans.data;
                    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                    TWCR = (1 << TWINT) | (1 << TWEN);
                    current_trans.state = I2C_STATE_DATA_W;
                }
            } else {
                current_trans.error = 1;
            }
            break;
        case I2C_STATE_DATA_W:
            if (status == 0x28) {
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN);
                current_trans.busy = 0;
            } else {
                current_trans.error = 1;
            }
            break;
        case I2C_STATE_REP_START:
            if (status == 0x10) {
                TWDR = 0xD1;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWEN);
                current_trans.state = I2C_STATE_SLA_R;
            } else {
                current_trans.error = 1;
            }
            break;
        case I2C_STATE_SLA_R:
            if (status == 0x40) {
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWEN);
                current_trans.state = I2C_STATE_DATA_R;
            } else {
                current_trans.error = 1;
            }
            break;
        case I2C_STATE_DATA_R:
            if (status == 0x58) {
                current_trans.data = TWDR;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN);
                current_trans.busy = 0;
            } else {
                current_trans.error = 1;
            }
            break;
        default:
            current_trans.error = 1;
            break;
    }

    if (current_trans.error) {
        // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
        TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN);
        current_trans.busy = 0;
    }
}

void drv_mpu6050_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR = 0x00;
    TWBR = 12;
    TWCR = (1 << TWEN);

    mpu_state = MPU_ST_INIT_WHOAMI;
    current_trans.busy = 0;
    mpu_data_valid = 0;
}

void drv_mpu6050_poll(void) {
    i2c_process();

    if (current_trans.busy) return;
    if (TWCR & (1 << TWSTO)) return;

    if (current_trans.error && mpu_state != MPU_ST_ERROR) {
        mpu_state = MPU_ST_ERROR;
        return;
    }

    switch (mpu_state) {
        case MPU_ST_INIT_WHOAMI:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_start_trans(0x75, 0, 1);
            mpu_state = MPU_ST_WAIT_WHOAMI;
            break;
        case MPU_ST_WAIT_WHOAMI:
            if (current_trans.data == 0x68) {
                mpu_state = MPU_ST_INIT_RESET;
            } else {
                mpu_state = MPU_ST_ERROR;
            }
            break;
        case MPU_ST_INIT_RESET:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_start_trans(0x6B, 0x80, 0);
            mpu_state = MPU_ST_WAIT_RESET;
            break;
        case MPU_ST_WAIT_RESET:
            delay_counter = 0;
            mpu_state = MPU_ST_DELAY_RESET;
            break;
        case MPU_ST_DELAY_RESET:
            break;
        case MPU_ST_INIT_WAKE:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_start_trans(0x6B, 0x01, 0);
            mpu_state = MPU_ST_WAIT_WAKE;
            break;
        case MPU_ST_WAIT_WAKE:
            mpu_state = MPU_ST_INIT_SMPLRT;
            break;
        case MPU_ST_INIT_SMPLRT:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_start_trans(0x19, 0x00, 0);
            mpu_state = MPU_ST_WAIT_SMPLRT;
            break;
        case MPU_ST_WAIT_SMPLRT:
            mpu_state = MPU_ST_INIT_CONFIG;
            break;
        case MPU_ST_INIT_CONFIG:
            // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
            i2c_start_trans(0x1A, 0x03, 0);
            mpu_state = MPU_ST_WAIT_CONFIG;
            break;
        case MPU_ST_WAIT_CONFIG:
            mpu_state = MPU_ST_IDLE;
            break;
        case MPU_ST_IDLE:
            break;
        case MPU_ST_START_READ:
            mpu_read_idx = 0;
            i2c_start_trans(mpu_regs[mpu_read_idx], 0, 1);
            mpu_state = MPU_ST_READING;
            break;
        case MPU_ST_READING:
            mpu_raw_data[mpu_read_idx] = current_trans.data;
            mpu_read_idx++;
            if (mpu_read_idx < 14) {
                i2c_start_trans(mpu_regs[mpu_read_idx], 0, 1);
            } else {
                mpu_latest_data.accel_x = (int16_t)(((uint16_t)mpu_raw_data[0] << 8) | mpu_raw_data[1]);
                mpu_latest_data.accel_y = (int16_t)(((uint16_t)mpu_raw_data[2] << 8) | mpu_raw_data[3]);
                mpu_latest_data.accel_z = (int16_t)(((uint16_t)mpu_raw_data[4] << 8) | mpu_raw_data[5]);
                mpu_latest_data.temp    = (int16_t)(((uint16_t)mpu_raw_data[6] << 8) | mpu_raw_data[7]);
                mpu_latest_data.gyro_x  = (int16_t)(((uint16_t)mpu_raw_data[8] << 8) | mpu_raw_data[9]);
                mpu_latest_data.gyro_y  = (int16_t)(((uint16_t)mpu_raw_data[10] << 8) | mpu_raw_data[11]);
                mpu_latest_data.gyro_z  = (int16_t)(((uint16_t)mpu_raw_data[12] << 8) | mpu_raw_data[13]);
                mpu_data_valid = 1;
                mpu_state = MPU_ST_IDLE;
            }
            break;
        case MPU_ST_ERROR:
            break;
    }
}

void drv_mpu6050_update(uint8_t dt_ms) {
    if (mpu_state == MPU_ST_DELAY_RESET) {
        delay_counter += dt_ms;
        if (delay_counter >= 100) {
            mpu_state = MPU_ST_INIT_WAKE;
        }
    } else if (mpu_state == MPU_ST_IDLE) {
        mpu_state = MPU_ST_START_READ;
    }
}

uint8_t drv_mpu6050_is_ready(void) {
    return mpu_data_valid;
}

void drv_mpu6050_get_data(mpu6050_data_t *data) {
    *data = mpu_latest_data;
}
